button.clickEventHandler:
var recallDateRequisite = data.requisites.find(function (_ref) {
  var name = _ref.name;
  return name === 'RecallDate';
});
if (recallDateRequisite.value != null) {
  ESS.actions.facilityActions.runFacility({id:'cbd8fbf7-e341-4f84-8e13-d8cb8e41f7ff'}, {parameters:{AssignmentId: data.id, AssignmentType: data.name}});
}
else {
  ESS.actions.facilityActions.runFacility({id:'d54a4fd2-a4cc-4e00-aa31-e4f692b334a6'}, {parameters:{AssignmentId: data.id, AssignmentType: data.name}});
}
ESS.closeElement(sender);

objectCard.openedEventHandler:
var assignmentId = data.id;
ESS.network.sendRequest(`/api/functions/GetReworkChangeReason?assignmentId=${assignmentId}`)
.then(function (denyReason) {
  ESS.network.sendRequest(`/api/functions/GetInstructionReworkVacation?assignmentId=${assignmentId}`)
  .then(function (instruction) {
    configuration.content = ESS.L('@HRPROVACATIONS.COMMON_INSTRUCTION') + '<br/><br/>' + instruction;
    data.reason = denyReason;
    resolve({configuration: configuration, data: data});
  })
})
.catch(function (error) {
  ESS.toasts.showToast(error.message, 'danger', false);
  reject();
});
